(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"आज सबै काम गरिसक्नु पर्दैन। अर्को सानो काम मात्र पुग्छ।\", \"थाक्नु भनेको हार्नु होइन। तिमी थाकेकी छौ, किनकि तिमी हरेक दिन साथमा रहन्छ्यौ।\", \"भाँडा कुर्न सक्छन्। पाँच मिनेट बस्ने तिम्रो पूरा अधिकार छ।\", \"बेलुकाको खानामा सिरियल दिनु पनि परिवारलाई खुवाउनु नै हो।\", \"आराम कमाउनु पर्दैन। तिमी अहिल्यै आराम गर्न सक्छ्यौ।\", \"कुनै दिन जित भनेकै सबै जना सुत्ने बेलासम्म ठीकसँग पुग्नु हो। यो साँचो जित हो।\", \"तिमी जति गर्छ्यौ, त्यति कसैले देख्दैन। म देख्छु।\", \"अस्तव्यस्त घर र मायामा हुर्केका बच्चा। यो राम्रो साटासाट हो।\", \"गाह्रो दिनमा तिम्रो सबैभन्दा राम्रो प्रयास फरक देखिन्छ, तर पनि त्यो गनिन्छ।\", \"एउटा लामो सास। काँध खुकुलो छोड। तिमी राम्रै गर्दैछ्यौ।\", \"आज अपेक्षा अलि घटाउनु ठीक छ। अर्को दिन फेरि बढाउन सक्छ्यौ।\", \"सहयोग माग्नु बलियो हुनु हो, कमजोरी होइन।\", \"अर्को एउटा कामलाई होइन भन्ने तिम्रो अधिकार छ।\", \"आज एक्लो महसुस भयो भने, यस्तो महसुस गर्ने तिमी मात्र आमा होइनौ। हामी धेरै छौँ।\", \"तिम्रो हालखबर सोध्ने र जवाफ पर्खने साथी पाउन तिमी योग्य छौ।\", \"पहिले आफैँ सम्पर्क गर्नु ठीक छ। धेरैजसो आमाहरू कसैले पहिले बोलोस् भन्ने आशा गरिरहेका हुन्छन्।\", \"कसैले नदेखेजस्तो लाग्नुको अर्थ तिमी महत्त्वपूर्ण छैनौ भन्ने होइन। तिमी धेरै महत्त्वपूर्ण छौ।\", \"तिम्रा भावना बुझ्न सकिने छन्। तिमी धेरै बढी होइनौ।\", \"यहाँ तिमीले आफ्नो गाह्रो दिन बुझाउनु पर्दैन। हामी बुझ्छौँ।\", \"अर्की आमालाई \\\"मलाई पनि\\\" भन्ने एउटा म्यासेजले पूरै दिन फेर्न सक्छ।\", \"खुवाउने, फेर्ने, झुलाउने, अनि फेरि उही। यो साँचो काम हो, बसिरहेजस्तो देखिए पनि।\", \"तिमी र तिम्रो बच्चा अझै एकअर्कालाई चिन्दैछौ। कुनै हतार छैन।\", \"नवजात शिशुसँगका दिन लामा हुन्छन्। यो समय सधैँ रहँदैन।\", \"आज तिमीले एउटा सानो मान्छेलाई अघाउञ्जेल खुवाएर न्यानो राख्यौ भने मात्र पनि, तिमीले ठूलो काम गर्‍यौ।\", \"छिट्टै पहिलेजस्तै हुनु पर्दैन। तिमी जहाँ छौ, त्यहीँ रहन सक्छ्यौ।\", \"बच्चालाई जसरी खुवाए पनि, तिमी उसको हेरचाह गर्दैछ्यौ। मुख्य कुरा यही हो।\", \"निद्रा कम र माया भरपूर, दुवै एकैसाथ हुन सक्छ।\", \"बच्चालाई काखमा लेऊ, घरको काम छाडिदेऊ। घर कतै जाँदैन।\", \"पसलमा बच्चाले गर्ने जिद्दीले तिमीलाई नराम्री आमा बनाउँदैन। यसको अर्थ मात्र तिम्रो बच्चा सानो छ भन्ने हो।\", \"साना बच्चाले सीमा जाँच्छन्, किनकि तिमीसँग उनीहरू सुरक्षित महसुस गर्छन्।\", \"आज तिमी हिजोभन्दा एक मिनेट बढी शान्त रह्यौ। यो पनि गनिन्छ।\", \"रिस उठेको थियो भने, एउटा अँगालो र एउटा \\\"माफ गर\\\" ले धेरै कुरा मिलाउँछ। अनि बच्चाहरूले राम्रो कुरा पनि सिक्छन्।\", \"टाँसिने हात, ठूला आवाज, ठूला भावना। तिमी एउटा पूरा मान्छे हुर्काउँदैछ्यौ।\", \"यो घण्टाको पाँचौँ \\\"किन?\\\" बढ्दै गरेको एउटा सानो दिमाग हो।\", \"खुसीको सम्झना बनाउन सिद्ध दिन चाहिँदैन।\", \"जोडले बन्द गरिएको ढोका कथाको अन्त्य होइन। बत्ती बालेर राख।\", \"तिम्रो किशोर छोराछोरीले भन्दैनन् होला, तर तिमी सधैँ साथमा हुनुको अर्थ ठूलो छ।\", \"घरमा शान्त रहने मान्छे हुनु कडा मिहिनेत हो। र तिमी त्यो गर्दैछ्यौ।\", \"केही सबैभन्दा राम्रा कुराकानी गाडीमा हुन्छन्। गाडी चलाइरह।\", \"उनीहरू ठूलो हुन टाढिन्छन्, तिमीलाई पछाडि छोड्न होइन।\", \"सबै प्रश्नको उत्तर थाहा हुनु पर्दैन। सुन्नु नै ठूलो कुरा हो।\", \"ठूला छोराछोरीलाई अझै तिम्रो खाँचो छ, बस अझ चुपचाप तरिकाले।\", \"सबै कुरा एक्लै धान्न यस्तो बल चाहिन्छ, जुन धेरैले कहिल्यै देख्दैनन्।\", \"तिमी आफ्नो बच्चाका लागि पर्याप्त राम्री आमा हौ। सधैँ थियौ।\", \"दुई हात, सय काम। आफूप्रति अलि नरम होऊ।\", \"तिम्रा बच्चाहरू तिमीलाई हेरेर बलियो र मायालु मान्छे कस्तो हुन्छ भनेर सिक्दैछन्।\", \"अलिकति विश्राम लिनु जिम्मेवारी छोड्नु होइन। यसैले तिमी अघि बढ्न सक्छ्यौ।\", \"कसैले हिसाब राखेको छैन। माया र साथमा हुनु, यही मुख्य हो।\", \"शोक र माया एउटै ठाउँबाट आउँछन्। कसैको याद आउनुले तिमीले कति माया गर्‍यौ भन्ने देखाउँछ।\", \"शोकको कुनै सही समयसीमा हुँदैन। जति समय चाहिन्छ, लेऊ।\", \"गाह्रा बरखीका दिनमा आफूप्रति त्यति नै कोमल होऊ, जति साथीप्रति हुन्थ्यौ।\", \"मनमा दुःख बोकेर पनि तिमी बच्चाहरूसँग हाँस्न सक्छ्यौ। दुवै साँचो हुन्।\", \"यदि तिमीले गर्भ वा बच्चा गुमायौ भने, त्यो क्षति साँचो हो, र तिम्रो माया पनि।\", \"कुनै दिन शोक चुपचाप हुन्छ, कुनै दिन चर्को। दुवै ठीक छन्।\", \"पैसाको कमीको अर्थ मायाको कमी होइन।\", \"तिम्रा बच्चाहरूलाई किनेका सामानभन्दा तिमीसँग बिताएको समय बढी याद रहनेछ।\", \"बिलका लागि सहयोगबारे सोध्नु बुद्धिमानी हो, लाजको कुरा होइन। सहयोग त्यसैका लागि त छ।\", \"पार्कमा बिनापैसाको एउटा दिउँसो हप्ताको सबैभन्दा राम्रो दिन बन्न सक्छ।\", \"तिमीले पैसा अझै एक हप्ता चलायौ। यसका लागि साँच्चै सीप चाहिन्छ।\", \"पैसाको चिन्ताले थकाउँछ। तिमीले धेरै बोकेकी छौ, तर पनि तिमी यहीँ छौ।\", \"आज तिमीले एक गिलास पानी पियौ। त्यहीँबाट सुरु गर।\", \"सबै जना ढोकाबाट निस्किए। जुत्ता मिलेनन् होला। तैपनि जित हो।\", \"जुन फोन गर्न डराइरहेकी थियौ, त्यो गरिहाल्यौ। त्यो साहस थियो।\", \"आज तिमी हाँस्यौ। त्यसलाई सम्हालेर राख।\", \"तातो खाना, सफा लुगा, सुत्ने बेलाको कथा। साना कुराहरू मिलेर बाल्यकाल बन्छ।\", \"आज तिमी कसैप्रति दयालु भयौ, चाहे त्यो आफूप्रति मात्र किन नहोस्।\", \"सिद्धता होइन, प्रगति। आज तिमी अघि बढ्यौ।\", \"सूचीको एउटा काम सक्यौ। केही नहुनुभन्दा एउटा बढी।\", \"तिमी राम्री आमा हौ। यसबारे चिन्ता गर्नुले नै तिमीलाई कति मतलब छ भन्ने देखाउँछ।\", \"एक दिनमा जति भ्याउँछ्यौ, तिमी त्योभन्दा धेरै बढी हौ।\", \"तिम्रा बच्चाहरूलाई सिद्ध आमा चाहिँदैन। उनीहरूलाई तिमी चाहिन्छ्यौ, र तिमी उनीहरूसँग छौ।\", \"आफ्ना बच्चाहरूसँग जति धैर्य राख्छ्यौ, आफूसँग पनि त्यति नै राख।\", \"आफ्नो ठाउँ लिने, केही चाहने र आफ्नै सपना देख्ने अधिकार तिमीलाई छ।\", \"एउटा गल्तीले माया मेटाउँदैन। भोलि नयाँ सुरुवात हो।\", \"तिमी कसैको पूरै संसार हौ, र तिमी आफैँमा पनि एउटा मान्छे हौ।\", \"हरेक पल मन नपर्नु ठीक छ। तैपनि तिमी आफ्ना बच्चाहरूलाई पूरा मनले माया गर्न सक्छ्यौ।\", \"आमा हुने एउटै सही तरिका छैन। तिम्रो तरिका पनि ठीक छ।\", \"वृक्षासनजस्तै, अलि डगमगाउनु ठीक छ। तिमी फेरि सन्तुलन पाउन सक्छ्यौ।\", \"ताडासनजस्तै खुट्टा जमाऊ। तिमीलाई लागेभन्दा तिमी बढी स्थिर छौ।\", \"वीरभद्रासन दुई: बलिया खुट्टा, खुला हात। यही तिमी हौ, यो हप्ताको सामना गर्दै।\", \"चार गनेर सास लेऊ, चार गनेर छोड। तिमी यहीँ छौ, र राम्रै गर्दैछ्यौ।\", \"ताराजस्तै फैलिएर तन्क। ठाउँ लिने तिम्रो अधिकार छ।\", \"चौडा र तल बसाइमा टिकिरहन गाह्रो हुन्छ। लामो दिन पनि त्यस्तै। र तिमी टिकेकी छौ।\", \"तिमी अर्धचन्द्रजस्तै ढल्किएर पनि उभिइरहन सक्छ्यौ।\", \"अहिल्यै खुट्टाका औँला छुनु पर्दैन। हरेक सानो तन्काइ पनि गनिन्छ।\", \"त्रिकोणासन: एउटा हात तल, एउटा माथि। जमिनसँग जोडिएर बस, र तन्किँदै जाऊ।\", \"धेरै राति भयो। आज नभएको काम भोलिसम्म पर्खन सक्छ।\", \"यो बेला बच्चासँग ब्युँझिरहेकी छौ? अहिले धेरै आमाहरू तिमीसँगै ब्युँझिरहेका छन्।\", \"घर शान्त छ। यो पल तिम्रो हो। सास फेर।\", \"तिमीले आजको दिन पार गर्‍यौ। आजलाई यति नै चाहिएको थियो।\", \"आज राति मन अशान्त छ भने, सबै लेखिदेऊ र बिहानसम्म पर्खन देऊ।\", \"आँखालाई आराम देऊ। भोलि फेरि सुरु गर्न सक्छ्यौ।\", \"चाडपर्व खुसीसँगै गाह्रो पनि हुन सक्छ। यो समय तिमीलाई जस्तो लागे पनि, ठीक छ।\", \"खानाको टेबल सिद्ध हुनु पर्दैन। वरिपरि बसेका मान्छे नै मुख्य हुन्।\", \"यो वर्ष टेबलमा कसैको अभाव खट्किन्छ भने, आफ्नो मनप्रति कोमल होऊ।\", \"धन्यवाद आमा, हरेक खाना, हरेक यात्रा र हरेक अँगालोका लागि।\", \"पाहुना बोलाउनु, परिकार बनाउनु वा सधैँ मुस्कुराइरहनु पर्दैन। सादा चाड पनि चाड नै हो।\", \"यो वर्ष तिम्रा बच्चाहरूले पाउने सबैभन्दा राम्रो उपहार तिमीसँग बिताएको समय हो।\", \"सानो उत्सव पनि मायाले भरिएको हुन्छ। विशेष बनाउन धेरै पैसा चाहिँदैन।\", \"चिसा दिन, न्याना अँगालो। तिमी नै आफ्नो घरको न्यानो कुना हौ।\", \"चाडपर्वको केही भागदौड छोड्नु ठीक छ। शान्ति पनि एउटा उपहार हो।\", \"यो वर्ष यो समय भारी लागिरहेको छ भने, तिमी एक्ली छैनौ। एक दिनमा एक दिन गरेर अघि बढ।\"]";D.body.appendChild(e)})();
